<?php
namespace App\Livewire;
use App\Models\SchoolClass;use App\Models\Subject;use App\Models\User;use Illuminate\Support\Facades\Auth;use Illuminate\Support\Facades\DB;use Livewire\Attributes\Layout;use Livewire\Component;
#[Layout('layouts.app')] class Subjects extends Component{public string $name='',$code='',$subjectId='',$classId='',$teacherId='';public function addSubject():void{$this->validate(['name'=>'required|string|max:255','code'=>'nullable|string|max:30']);Subject::firstOrCreate(['school_id'=>Auth::user()->school_id,'name'=>$this->name],['code'=>$this->code?:null]);$this->reset(['name','code']);session()->flash('status','Subject saved.');}public function assign():void{$school=Auth::user()->school;$term=$school->currentTerm();if(!$term){session()->flash('error','Open a term before assigning subjects.');return;}$this->validate(['subjectId'=>'required|exists:subjects,id','classId'=>'required|exists:school_classes,id','teacherId'=>'required|exists:users,id']);DB::transaction(function()use($school,$term){$offering=DB::table('class_subjects')->where(['term_id'=>$term->id,'school_class_id'=>$this->classId,'subject_id'=>$this->subjectId])->first();if(!$offering){DB::table('class_subjects')->insert(['school_id'=>$school->id,'term_id'=>$term->id,'school_class_id'=>$this->classId,'subject_id'=>$this->subjectId,'created_at'=>now(),'updated_at'=>now()]);}DB::table('staff_subjects')->updateOrInsert(['school_id'=>$school->id,'term_id'=>$term->id,'user_id'=>$this->teacherId,'subject_id'=>$this->subjectId,'school_class_id'=>$this->classId],['updated_at'=>now(),'created_at'=>now()]);});session()->flash('status','Subject assigned for the current term.');}public function render(){$school=Auth::user()->school;return view('livewire.subjects',['term'=>$school->currentTerm(),'subjects'=>Subject::where('school_id',$school->id)->orderBy('name')->get(),'classes'=>SchoolClass::where('school_id',$school->id)->orderBy('name')->get(),'teachers'=>User::where('school_id',$school->id)->where('employment_status','active')->where('role','teacher')->orderBy('name')->get(),'pageTitle'=>'Subjects']);}}
